-- Expense claims submitted by employees.
-- All amounts are in EUR for now, stored as integer cents to avoid rounding errors.

-- +goose Up
CREATE SCHEMA IF NOT EXISTS expenses;

CREATE TABLE expenses.claims (
    -- Generated by the Go service so the ID is known before the insert.
    id           uuid        PRIMARY KEY,
    employee_id  text        NOT NULL,
    amount_cents bigint      NOT NULL,
    description  text        NOT NULL,
    status       text        NOT NULL DEFAULT 'pending',
    created_at   timestamptz NOT NULL DEFAULT now(),

    -- '\S' requires at least one non-whitespace character,
    -- so '' and strings of spaces, tabs or newlines are rejected.
    CONSTRAINT claims_employee_id_not_blank CHECK (employee_id ~ '\S'),
    CONSTRAINT claims_description_not_blank CHECK (description ~ '\S'),
    CONSTRAINT claims_amount_positive       CHECK (amount_cents > 0),
    CONSTRAINT claims_status_valid          CHECK (status IN ('pending', 'approved', 'rejected'))
);

-- +goose Down
DROP TABLE expenses.claims;
DROP SCHEMA expenses;
